'use strict';

// MODULES //

var isInteger = require( '@stdlib/math/base/assert/is-integer' );
var isArray = require( '@stdlib/assert/is-array' );


// MAIN //

/**
* Returns a string containing environment variables for generating pseudorandom numbers.
*
* @private
* @param {Object} obj - configuration object
* @returns {string} environment variable string
*
* @example
* var o = {
*     'prng': 'random/base/uniform',
*     'parameters': [ -10, 10 ]
* };
*
* var s = prngEnvVars( o );
* // returns 'BASE_PRNG=\'uniform\' RAND_MIN=-10.0 RAND_MAX=10.0'
*/
function prngEnvVars( obj ) {
	var base;
	var min;
	var max;
	var p;

	p = obj.prng.split( '/' );
	base = p[ p.length-1 ];

	// TODO: Handle different ranges for both real and imaginary components. Currently, we are only considering min and max as the first two elements of the first row of the array, in case of complex numbers.
	if ( isArray( obj.parameters[ 0 ] ) ) {
		min = obj.parameters[ 0 ][ 0 ];
		max = obj.parameters[ 0 ][ 1 ];
	} else {
		min = obj.parameters[ 0 ];
		max = obj.parameters[ 1 ];
	}
	if ( base === 'uniform' ) {
		if ( isInteger( min ) ) {
			min = min.toString() + '.0';
		}
		if ( isInteger( max ) ) {
			max = max.toString() + '.0';
		}
	} else {
		min = min.toString();
		max = max.toString();
	}
	return [
		'BASE_PRNG=\'' + base + '\'',
		'RAND_MIN=' + min,
		'RAND_MAX=' + max
	].join( ' ' );
}


// EXPORTS //

module.exports = prngEnvVars;
